}

func TestChannelComparisonAggregatesPerChannel(t *testing.T) {
	st := openTestStore(t)
	seedComparisonRecords(t, st)

	result, err := st.ChannelComparison(context.Background(), mustComparison(t, func(in *delivery.ComparisonInput) {}))
