			t.Fatalf("channel %d = %s, want %s", i, result.Channels[i], want)
		}
	}

	if result.TotalAttempts["sms"] != 3 || result.TotalAttempts["email"] != 3 || result.TotalAttempts["push"] != 1 {
		t.Fatalf("totals = %+v", result.TotalAttempts)
	}
