		t.Fatalf("channels = %v, want %v", result.Channels, wantChannels)
	}
	for i, want := range wantChannels {
		if result.Channels[i] != want {
			t.Fatalf("channel %d = %s, want %s", i, result.Channels[i], want)
		}
	}

